package ganymedes01.etfuturum;
import net.minecraft.entity.*;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.init.*;
import net.minecraft.item.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.world.World;
import net.minecraftforge.event.entity.living.LivingDeathEvent;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
/** Server-owned saved navigation; inventory NBT uses the native slot synchronization. */
public final class NavigationItems {
 public static final String TARGET="UabCompassTarget",DEATH="UabLastDeath";private NavigationItems(){}
static void define(){Content.add("lodestone","content.lodestones",new LodestoneBlock());Content.add("lodestone_compass","content.lodestones",new TargetCompass(false));Content.add("recovery_compass","content.recovery_compasses",new TargetCompass(true));Content.add("echo_shard","experiments.enableSculk",new Item());net.minecraftforge.common.MinecraftForge.EVENT_BUS.register(new NavigationItems());}
 static void recipes(net.minecraftforge.event.RegistryEvent.Register<net.minecraft.item.crafting.IRecipe> event){Crafting.shaped(event,"lodestone",Content.stack("lodestone"),"BBB","BIB","BBB",'B',new ItemStack(Blocks.STONEBRICK,1,3),'I',Items.IRON_INGOT);Crafting.shaped(event,"recovery_compass",Content.stack("recovery_compass"),"EEE","ECE","EEE",'E',Content.item("echo_shard"),'C',Items.COMPASS);}
 public static NBTTagCompound target(int dimension,int x,int y,int z){NBTTagCompound target=new NBTTagCompound();target.setInteger("Dimension",dimension);target.setInteger("X",x);target.setInteger("Y",y);target.setInteger("Z",z);return target;}
 public static boolean valid(NBTTagCompound target){return target.hasKey("Dimension",99)&&target.hasKey("X",99)&&target.hasKey("Y",99)&&target.hasKey("Z",99);}
 public static NBTTagCompound saved(EntityPlayer player){return player.getEntityData().getCompoundTag(EntityPlayer.PERSISTED_NBT_TAG).getCompoundTag(DEATH);}
 private static void remember(EntityPlayer player,NBTTagCompound target){NBTTagCompound data=player.getEntityData().getCompoundTag(EntityPlayer.PERSISTED_NBT_TAG);data.setTag(DEATH,target.copy());player.getEntityData().setTag(EntityPlayer.PERSISTED_NBT_TAG,data);}
 @SubscribeEvent public void death(LivingDeathEvent event){if(!(event.getEntityLiving() instanceof EntityPlayer)||event.getEntityLiving().world.isRemote)return;EntityPlayer player=(EntityPlayer)event.getEntityLiving();remember(player,target(player.world.provider.getDimension(),(int)Math.floor(player.posX),(int)Math.floor(player.posY),(int)Math.floor(player.posZ)));}
 @SubscribeEvent public void clone(PlayerEvent.Clone event){NBTTagCompound target=saved(event.getOriginal());if(valid(target))remember(event.getEntityPlayer(),target);}
 public static void update(ItemStack stack,World world,Entity entity,boolean recovery){if(world.isRemote||!(entity instanceof EntityPlayer))return;EntityPlayer player=(EntityPlayer)entity;NBTTagCompound root=stack.hasTagCompound()?stack.getTagCompound():new NBTTagCompound(),previous=root.getCompoundTag(TARGET);if(recovery){NBTTagCompound next=saved(player);if(valid(next)){if(!previous.equals(next)){root.setTag(TARGET,next.copy());stack.setTagCompound(root);player.inventory.markDirty();}}else if(root.hasKey(TARGET)){root.removeTag(TARGET);stack.setTagCompound(root);player.inventory.markDirty();}}else if(valid(previous)&&player.ticksExisted%20==0&&previous.getInteger("Dimension")==world.provider.getDimension()){int x=previous.getInteger("X"),y=previous.getInteger("Y"),z=previous.getInteger("Z");if(world.isBlockLoaded(new net.minecraft.util.math.BlockPos(x,y,z))&&world.getBlockState(new net.minecraft.util.math.BlockPos(x,y,z)).getBlock()!=Content.block("lodestone")){root.removeTag(TARGET);stack.setTagCompound(root);player.inventory.markDirty();}}}
 public static boolean bind(EntityPlayer player,World world,net.minecraft.util.math.BlockPos pos,net.minecraft.util.EnumHand hand){ItemStack held=player.getHeldItem(hand);if(held.isEmpty()||!(held.getItem()==Items.COMPASS||held.getItem() instanceof TargetCompass&&!(( TargetCompass)held.getItem()).recovery))return false;if(world.isRemote)return true;ItemStack bound=new ItemStack(Content.item("lodestone_compass"));NBTTagCompound tag=held.hasTagCompound()?(NBTTagCompound)held.getTagCompound().copy():new NBTTagCompound();tag.setTag(TARGET,target(player.world.provider.getDimension(),pos.getX(),pos.getY(),pos.getZ()));bound.setTagCompound(tag);if(!player.capabilities.isCreativeMode&&held.getCount()==1){player.setHeldItem(hand,bound);}else{if(!player.capabilities.isCreativeMode){held.shrink(1);}if(!player.inventory.addItemStackToInventory(bound))player.dropItem(bound,false);}player.inventory.markDirty();return true;}
}
